// One-off: export the geo reference hierarchy (attributes only, no geometry)
// from the local GIS database into a committed migration file.
import 'dotenv/config';
import pg from 'pg';
import fs from 'node:fs';

const pool = new pg.Pool({ connectionString: process.env.DATABASE_URL });
const q = (s) => (s === null || s === undefined ? 'null' : `'${String(s).replace(/'/g, "''")}'`);

const HEAD = `-- Northern Province geo reference hierarchy — district / DS / GN divisions.
--
-- GENERATED by scripts/export-geo.mjs from the northern_province GIS database
-- (attributes only: codes and names, no geometry). The membership app reads
-- nothing but codes + name_en from these tables, so shipping them here removes
-- the app's dependency on the GIS database and lets it deploy against any plain
-- Postgres — no PostGIS required.
--
-- Only the LK* hierarchy is exported. The GIS database also holds a set of
-- orphan district rows ('41'..'45', province '4') with no DS children and no
-- geometry — a duplicate import. Those are deliberately excluded: with them
-- present there are two districts named 'Jaffna', and 0003_events.sql used
-- "geom is not null" to tell them apart. Since geometry does not travel with
-- this export, dropping the orphans is what keeps that lookup unambiguous.
--
-- Idempotent and safe against the shared local GIS database: the CREATEs are
-- "if not exists" (so the real PostGIS-backed tables are left untouched) and
-- every insert is "on conflict do nothing".

begin;

create schema if not exists geo;

create table if not exists geo.province (
  province_code text primary key,
  name_en       text,
  name_ta       text,
  name_si       text
);

create table if not exists geo.district (
  district_code text primary key,
  province_code text,
  name_en       text,
  name_ta       text,
  name_si       text
);

create table if not exists geo.ds_division (
  ds_code       text primary key,
  district_code text,
  name_en       text,
  name_ta       text,
  name_si       text
);

create table if not exists geo.gn_division (
  gn_code text primary key,
  ds_code text,
  name_en text,
  name_ta text,
  name_si text
);

create index if not exists district_province_idx on geo.district(province_code);
create index if not exists ds_division_district_idx on geo.ds_division(district_code);
create index if not exists gn_division_ds_idx on geo.gn_division(ds_code);
`;

// Every table is filtered down to the connected hierarchy: a DS division must
// belong to a real district, a district must have DS children, a province must
// have districts. This drops the orphan '41'..'45' / province '4' rows.
const LIVE_DISTRICTS = `SELECT DISTINCT district_code FROM geo.ds_division WHERE district_code IS NOT NULL`;

const TABLES = [
  {
    name: 'province',
    cols: ['province_code', 'name_en', 'name_ta', 'name_si'],
    order: 'province_code',
    where: `province_code IN (SELECT province_code FROM geo.district WHERE district_code IN (${LIVE_DISTRICTS}))`,
  },
  {
    name: 'district',
    cols: ['district_code', 'province_code', 'name_en', 'name_ta', 'name_si'],
    order: 'district_code',
    where: `district_code IN (${LIVE_DISTRICTS})`,
  },
  {
    name: 'ds_division',
    cols: ['ds_code', 'district_code', 'name_en', 'name_ta', 'name_si'],
    order: 'ds_code',
    where: `district_code IN (${LIVE_DISTRICTS})`,
  },
  {
    name: 'gn_division',
    cols: ['gn_code', 'ds_code', 'name_en', 'name_ta', 'name_si'],
    order: 'gn_code',
    where: `ds_code IN (SELECT ds_code FROM geo.ds_division WHERE district_code IN (${LIVE_DISTRICTS}))`,
  },
];

let out = HEAD;
for (const t of TABLES) {
  const r = await pool.query(`SELECT ${t.cols.join(', ')} FROM geo.${t.name} WHERE ${t.where} ORDER BY ${t.order}`);
  out += `\n-- geo.${t.name} — ${r.rows.length} rows\n`;
  // Chunked multi-row inserts: readable diffs, and no single statement so large
  // that a constrained free-tier connection chokes on it.
  for (let i = 0; i < r.rows.length; i += 100) {
    const chunk = r.rows.slice(i, i + 100);
    out += `insert into geo.${t.name} (${t.cols.join(', ')}) values\n`;
    out += chunk.map((row) => `  (${t.cols.map((c) => q(row[c])).join(', ')})`).join(',\n');
    out += `\non conflict do nothing;\n`;
  }
  console.log(`geo.${t.name}: ${r.rows.length} rows`);
}
out += '\ncommit;\n';

const dest = process.argv[2];
fs.writeFileSync(dest, out, 'utf8');
console.log(`\nwrote ${dest} — ${(Buffer.byteLength(out) / 1024).toFixed(0)} KB`);
await pool.end();
